// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 depositAmt, uint256 amount) public {
        vm.assume(depositAmt <= VALUE_CAP);
        address actor = address(0xA11CE);
        vm.assume(depositAmt > 0);
        vm.assume(amount > 0);
        vm.assume(amount <= depositAmt);

        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.deposit{value: depositAmt}();

        // Any amount up to (and including) the full balance is withdrawable:
        // the transfer must go through and the contract balance must drop by exactly `amount`.
        vm.prank(actor);
        try c.withdraw(amount) {
            // success path: balance must have decreased by exactly amount
        } catch {
            // even a revert must not change the contract balance
        }

        assertTrue(address(c).balance == depositAmt - amount);
    }
}
